`,u.jsx(n.p,{children:"If I were to revisit this project, I would prioritize observability. Proper logging, alerting, and monitoring would have saved me hours of debugging when the server went down. I’d also implement automated Docker cleanup policies and better resource tracking."}),`
`,u.jsx(n.p,{children:"On the product side, I’d expand beyond the top 100 movies and add filtering, historical trends, or even heatmaps of filming density. The visualization layer has room to grow - both in performance and interactivity — but the foundation is solid."})]})}function DA(i={}){const{wrapper:n}=i.components||{};return n?u.jsx(n,{...i,children:u.jsx(My,{...i})}):My(i)}function Dy(i){const n={h2:"h2",hr:"hr",li:"li",p:"p",ul:"ul",...i.components};return u.jsxs(u.Fragment,{children:[u.jsx(n.hr,{}),`
`,u.jsx(n.h2,{children:"Introduction"}),`
`,u.jsx(n.p,{children:"“I Want To RAGE” was built during NUS Hack&Roll 2026 as a last-minute idea that somehow became our main project. The concept was simple: what if you could safely destroy your Google widgets when you’re stressed - without actually breaking anything?"}),`
`,u.jsx(n.p,{children:"The inspiration came from stickman destruction animations on YouTube. I wanted to recreate that chaotic, over-the-top energy, but inside the browser. Instead of animating characters, I thought: why not let users tear apart the very UI elements they interact with daily ?"}),`
`,u.jsx(n.p,{children:"The result is a Chrome web extension that converts Google widgets into destructible objects. Users can toggle a flamethrower mode, click to slice widgets in half, and physically throw them around the screen - all built using vanilla web technologies."}),`
`,u.jsx(n.hr,{}),`
`,u.jsx(n.h2,{children:"Intuition"}),`
`,u.jsxs(n.ul,{children:[`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Browser extensions require careful DOM manipulation without breaking page functionality."}),`
`]}),`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Widgets need to be extracted from the DOM while preserving visual fidelity."}),`
`]}),`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Destruction mechanics require physics simulation and object state management."}),`
`]}),`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Performance must remain stable despite rapid user input."}),`
`]}),`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Some sites intentionally obscure class names to prevent scraping or manipulation."}),`
`]}),`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Rendering destruction effects needs to avoid excessive DOM reflows."}),`
`]}),`
`]}),`
`,u.jsx(n.hr,{}),`
`,u.jsx(n.h2,{children:"Process"}),`
`,u.jsx(n.p,{children:"This project was built entirely with vanilla JavaScript, HTML, and CSS. No frameworks - just raw browser APIs. The hardest problem early on was figuring out how to make existing widgets “destructible.” Removing them directly from the DOM broke layout and caused visual glitches. I needed a way to visually detach them without breaking the page itself."}),`
`,u.jsx(n.p,{children:"The breakthrough was using HTML Canvas. Instead of manipulating the live DOM nodes directly, I used html2canvas to render widgets into bitmap images. Once converted into canvas-rendered objects, I could treat them like independent entities - positioned absolutely and animated freely. This created the illusion that the widgets were being “taken off the shelves.”."}),`
`,u.jsx(n.p,{children:"Targeting widgets was tricky. Some sites randomize class names or rely heavily on nested div structures to guard against scraping or bot manipulation. Relying purely on class selectors was unreliable. I had to build more resilient DOM traversal logic based on structure and hierarchy instead of fixed identifiers."}),`
`,u.jsx(n.p,{children:"For physics simulation, I integrated a lightweight library to create a playground-like environment where widgets could be thrown around realistically. Clicking a widget slices it in half - which required re-rendering the two split sections separately using html2canvas again. Each half becomes its own physics object."}),`
`,u.jsx(n.p,{children:"The flamethrower mode was an extra layer of state logic. Pressing F toggles between cursor and flamethrower. When active, holding click applies damage over time. Widgets are assigned health values, and their colors darken progressively before splitting apart once health reaches zero. Managing these state transitions without freezing the browser required careful throttling of event listeners."}),`
`,u.jsx(n.p,{children:"Performance is hardware-dependent. Rapid clicking can spawn too many canvas redraws and physics updates, which can degrade performance. While reloads typically resolve minor issues, it’s clear the rendering pipeline could be optimized further."}),`
`,u.jsx(n.hr,{}),`
`,u.jsx(n.h2,{children:"What I Learned"}),`
`,u.jsxs(n.ul,{children:[`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Deep DOM manipulation without breaking layout integrity"}),`
`]}),`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Rendering DOM elements into canvas bitmaps using html2canvas"}),`
`]}),`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Managing object state and health systems in pure JavaScript"}),`
`]}),`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Handling performance bottlenecks caused by excessive event firing"}),`
`]}),`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Building physics-style interactions inside the browser"}),`
`]}),`
`,u.jsxs(n.li,{children:[`
`,u.jsx(n.p,{children:"Designing browser extensions with safe fallbacks for restricted sites"}),`
`]}),`
`]}),`
`,u.jsx(n.hr,{}),`
`,u.jsx(n.h2,{children:"What's Next"}),`
`,u.jsx(n.p,{children:"The biggest improvement area is performance optimization. Rapid interactions can overwhelm the canvas redraw cycle and physics engine. I’d like to implement better object pooling, input throttling, and possibly Web Workers to offload heavy calculations."}),`
`,u.jsx(n.p,{children:"I’d also refine widget targeting to be more adaptive across different Google surfaces. The core destruction mechanics work - but improving stability, smoothness, and compatibility would make it feel far more polished."})]})}function RA(i={}){const{wrapper:n}=i.components||{};return n?u.jsx(n,{...i,children:u.jsx(Dy,{...i})}):Dy(i)}function Ry(i){const n={h2:"h2",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...i.components};return u.jsxs(u.Fragment,{children:[u.jsx(n.hr,{}),`
`,u.jsx(n.h2,{children:"Introduction"}),`
`,u.jsx(n.p,{children:"During one of my university Java projects, my team and I built a modular face recognition attendance management system using Java, OpenCV, and ONNX (ArcFace)."}),`
`,u.jsx(n.p,{children:"It was a full desktop application with authentication, session management, live recognition, reporting, and configuration controls."}),`
`,u.jsx(n.p,{children:"I was responsible for designing and implementing the entire reporting subsystem — including CSV, Excel, and PDF exports - as well as building a historical reports interface inside the dashboard."}),`
